spec.expr:
clamp_max(
  (
    sum(
      kube_deployment_spec_replicas{
        namespace="argocd",
        deployment=~"argocd-(applicationset-controller|dex-server|notifications-controller|redis|repo-server|server)",
        exported_job="kube-state-metrics"
      }
      -
      kube_deployment_status_replicas_available{
        namespace="argocd",
        deployment=~"argocd-(applicationset-controller|dex-server|notifications-controller|redis|repo-server|server)",
        exported_job="kube-state-metrics"
      }
    )
    or vector(1)
  )
  +
  (
    sum(
      kube_statefulset_replicas{
        namespace="argocd",
        statefulset="argocd-application-controller",
        exported_job="kube-state-metrics"
      }
      -
      kube_statefulset_status_replicas_ready{
        namespace="argocd",
        statefulset="argocd-application-controller",
        exported_job="kube-state-metrics"
      }
    )
    or vector(1)
  ),
  1
)

clamp_max(
  kube_deployment_spec_replicas{
    namespace="kyverno",
    exported_job="kube-state-metrics"
  }
  -
  kube_deployment_status_replicas_available{
    namespace="kyverno",
    exported_job="kube-state-metrics"
  },
  1
)

clamp_max(
  kube_deployment_spec_replicas{
    namespace="graph-proxy",
    deployment="graph-proxy",
    exported_job="kube-state-metrics"
  }
  -
  kube_deployment_status_replicas_available{
    namespace="graph-proxy",
    deployment="graph-proxy",
    exported_job="kube-state-metrics"
  },
  1
)

100 *
sum(
  rate(
    graph_proxy_errors_total{
      k8s_namespace_name="graph-proxy"
    }[5m]
  )
)
/
clamp_min(
  sum(
    rate(
      graph_proxy_requests_total{
        k8s_namespace_name="graph-proxy"
      }[5m]
    )
  ),
  0.000001
)

clamp_max(
  (
    sum(
      kube_deployment_spec_replicas{
        namespace="workflows",
        deployment=~".*(workflow-controller|argo-server|workflows-server).*",
        exported_job="kube-state-metrics"
      }
      -
      kube_deployment_status_replicas_available{
        namespace="workflows",
        deployment=~".*(workflow-controller|argo-server|workflows-server).*",
        exported_job="kube-state-metrics"
      }
    )
    or vector(1)
  )
  +
  (
    1 -
    min(
      up{
        job="otel-collector",
        namespace="workflows",
        app_kubernetes_io_part_of="argo-workflows"
      }
    )
    or vector(1)
  ),
  1
)

clamp_max(
  kube_deployment_spec_replicas{
    namespace="kueue",
    deployment="kueue-controller-manager"
  }
-
  kube_deployment_status_replicas_available{
    namespace="kueue",
    deployment="kueue-controller-manager"
  },
  1
)

kueue_cluster_queue_nominal_quota{
  cluster_queue="default-queue",
  flavor="default-flavor",
  resource="cpu"
}
-
kueue_cluster_queue_resource_usage{
  cluster_queue="default-queue",
  flavor="default-flavor",
  resource="cpu"
}

kueue_cluster_queue_nominal_quota{
  cluster_queue="default-queue",
  flavor="default-flavor",
  resource="nvidia.com/gpu"
}
-
kueue_cluster_queue_resource_usage{
  cluster_queue="default-queue",
  flavor="default-flavor",
  resource="nvidia.com/gpu"
}

clamp_max(
  kube_deployment_spec_replicas{
    namespace="workflows",
    exported_job="kube-state-metrics",
    deployment=~"auth-gateway|dashboard|workflows-argo-workflows-server|workflows-argo-workflows-workflow-controller|workflows-oauth2-proxy|workflows-postgresql-ha-pgpool"
  }
  -
  kube_deployment_status_replicas_available{
    namespace="workflows",
    exported_job="kube-state-metrics",
    deployment=~"auth-gateway|dashboard|workflows-argo-workflows-server|workflows-argo-workflows-workflow-controller|workflows-oauth2-proxy|workflows-postgresql-ha-pgpool"
  },
  1
)

1 -
max by (pod) (
  kube_pod_status_ready{
    namespace="workflows",
    condition="true",
    pod=~"workflows-postgresql-ha-postgresql-[0-9]+",
    exported_job="kube-state-metrics"
  }
)

max(
  100 *
  sum by (namespace, pod) (
    pg_stat_activity_count{
      namespace="workflows",
      job="otel-collector",
      app_kubernetes_io_instance="workflows",
      app_kubernetes_io_component="postgresql",
      pod!=""
    }
  )
  /
  on (namespace, pod)
  max by (namespace, pod) (
    pg_settings_max_connections{
      namespace="workflows",
      job="otel-collector",
      app_kubernetes_io_instance="workflows",
      app_kubernetes_io_component="postgresql",
      pod!=""
    }
  )
)
